from __future__ import annotations

from dataclasses import dataclass, field
from enum import Enum
from typing import Any, Mapping, Protocol

from pydantic import BaseModel, ConfigDict, Field


class IdentityProvider(str, Enum):
    OIDC = "oidc"
    SAML = "saml"


@dataclass(frozen=True)
class PermissionCatalog:
    group_permissions: Mapping[str, frozenset[str]] = field(default_factory=dict)
    role_permissions: Mapping[str, frozenset[str]] = field(default_factory=dict)

    def permissions_for(
        self,
        *,
        groups: tuple[str, ...],
        roles: tuple[str, ...],
    ) -> frozenset[str]:
        granted: set[str] = set()

        for group in groups:
            granted.update(self.group_permissions.get(group, frozenset()))

        for role in roles:
            granted.update(self.role_permissions.get(role, frozenset()))

        return frozenset(sorted(granted))

    @classmethod
    def from_raw(
        cls,
        *,
        group_permissions: Mapping[str, set[str] | frozenset[str] | tuple[str, ...]] | None = None,
        role_permissions: Mapping[str, set[str] | frozenset[str] | tuple[str, ...]] | None = None,
    ) -> "PermissionCatalog":
        normalized_groups = {
            str(key).strip().casefold(): frozenset(
                sorted(str(permission).strip().casefold() for permission in values if str(permission).strip()),
            )
            for key, values in (group_permissions or {}).items()
            if str(key).strip()
        }
        normalized_roles = {
            str(key).strip().casefold(): frozenset(
                sorted(str(permission).strip().casefold() for permission in values if str(permission).strip()),
            )
            for key, values in (role_permissions or {}).items()
            if str(key).strip()
        }
        return cls(
            group_permissions=normalized_groups,
            role_permissions=normalized_roles,
        )


@dataclass(frozen=True)
class ActorContext:
    actor_id: str
    provider: IdentityProvider
    subject: str
    username: str
    display_name: str
    email: str | None
    groups: tuple[str, ...]
    roles: tuple[str, ...]
    permissions: frozenset[str]


@dataclass(frozen=True)
class MutationCommand:
    operation: str
    target_id: str
    payload: Mapping[str, Any]
    actor_id: str
    actor_username: str
    actor_permissions: frozenset[str]


@dataclass(frozen=True)
class MutationResult:
    mutation_id: str
    status: str = "applied"


@dataclass(frozen=True)
class AuditEvent:
    event_type: str
    actor_id: str
    target_id: str
    details: Mapping[str, Any]


class MutationWriter(Protocol):
    def write(self, command: MutationCommand) -> MutationResult:
        ...


class AuditSink(Protocol):
    def record(self, event: AuditEvent) -> None:
        ...


class ActorResponse(BaseModel):
    model_config = ConfigDict(extra="forbid", frozen=True)

    actor_id: str
    provider: IdentityProvider
    subject: str
    username: str
    display_name: str
    email: str | None = None
    groups: list[str] = Field(default_factory=list)
    roles: list[str] = Field(default_factory=list)
    permissions: list[str] = Field(default_factory=list)


class ProtectedWriteRequest(BaseModel):
    model_config = ConfigDict(extra="forbid")

    target_id: str = Field(min_length=1)
    payload: dict[str, Any] = Field(default_factory=dict)


class ProtectedWriteResponse(BaseModel):
    model_config = ConfigDict(extra="forbid", frozen=True)

    mutation_id: str
    status: str
    target_id: str
    actor_id: str


