from __future__ import annotations

import json
import logging
import sys
from pathlib import Path

import pytest
from fastapi import FastAPI
from fastapi.testclient import TestClient

REQ_ROOT = Path(__file__).resolve().parents[3]
SRC_ROOT = REQ_ROOT / "src"
if str(SRC_ROOT) not in sys.path:
    sys.path.insert(0, str(SRC_ROOT))

from backend.auth.binding import create_auth_router
from backend.auth.contracts import AuditEvent, MutationCommand, MutationResult, PermissionCatalog
from backend.auth.implementation import AuthSessionService, AuthorizationFailure


class RecordingWriter:
    def __init__(self) -> None:
        self.commands: list[MutationCommand] = []

    def write(self, command: MutationCommand) -> MutationResult:
        self.commands.append(command)
        return MutationResult(mutation_id=f"mut-{len(self.commands)}")


class RecordingAuditSink:
    def __init__(self) -> None:
        self.events: list[AuditEvent] = []

    def record(self, event: AuditEvent) -> None:
        self.events.append(event)


def _permission_catalog() -> PermissionCatalog:
    return PermissionCatalog.from_raw(
        group_permissions={
            "finance-readers": {"documents.read"},
            "finance-editors": {"documents.read", "documents.write"},
        },
        role_permissions={
            "validator": {"documents.validate"},
        },
    )


def _build_client() -> tuple[TestClient, RecordingWriter, RecordingAuditSink]:
    writer = RecordingWriter()
    audit = RecordingAuditSink()

    app = FastAPI()
    app.include_router(
        create_auth_router(
            mutation_writer=writer,
            audit_sink=audit,
            permission_catalog=_permission_catalog(),
        ),
    )

    return TestClient(app), writer, audit


def _headers(
    *,
    provider: str,
    claims: dict[str, object],
    include_secrets: bool = False,
) -> dict[str, str]:
    headers = {
        "x-auth-provider": provider,
        "x-auth-claims": json.dumps(claims),
    }
    if include_secrets:
        headers["authorization"] = "Bearer secret-token-value"
        headers["x-saml-assertion"] = "<Assertion>secret-assertion</Assertion>"
    return headers


def test_claims_map_to_permissions_deterministically_for_oidc_and_saml() -> None:
    service = AuthSessionService(permission_catalog=_permission_catalog())

    oidc_claims = {
        "sub": "user-123",
        "preferred_username": "Alice",
        "name": "Alice Example",
        "email": "alice@example.com",
        "groups": ["finance-editors"],
        "roles": ["validator"],
        "scope": "documents.read",
    }
    saml_claims = {
        "nameid": "alice@example.com",
        "http://schemas.xmlsoap.org/ws/2005/05/identity/claims/name": "Alice Example",
        "http://schemas.xmlsoap.org/ws/2005/05/identity/claims/emailaddress": "alice@example.com",
        "http://schemas.xmlsoap.org/claims/group": ["finance-editors"],
        "http://schemas.microsoft.com/ws/2008/06/identity/claims/role": ["validator"],
        "permissions": ["documents.read"],
    }

    oidc_actor_first = service.authenticate_headers(_headers(provider="oidc", claims=oidc_claims))
    oidc_actor_second = service.authenticate_headers(_headers(provider="oidc", claims=oidc_claims))
    saml_actor = service.authenticate_headers(_headers(provider="saml", claims=saml_claims))

    assert oidc_actor_first == oidc_actor_second
    assert oidc_actor_first.actor_id == "oidc:user-123"
    assert oidc_actor_first.username == "alice"
    assert oidc_actor_first.permissions == frozenset(
        {
            "documents.read",
            "documents.write",
            "documents.validate",
        },
    )

    assert saml_actor.actor_id == "saml:alice@example.com"
    assert saml_actor.email == "alice@example.com"
    assert saml_actor.permissions == frozenset(
        {
            "documents.read",
            "documents.write",
            "documents.validate",
        },
    )


def test_deny_when_required_permission_missing_and_do_not_mutate() -> None:
    client, writer, audit = _build_client()

    response = client.post(
        "/auth/protected-write",
        headers=_headers(
            provider="oidc",
            claims={
                "sub": "reader-001",
                "preferred_username": "reader",
                "groups": ["finance-readers"],
            },
        ),
        json={"target_id": "doc-1", "payload": {"status": "validated"}},
    )

    assert response.status_code == 403
    assert response.json()["detail"] == "Caller does not have the required permission."
    assert writer.commands == []
    assert audit.events == []


def test_get_auth_me_returns_normalized_actor_for_fixture_identity() -> None:
    client, _, _ = _build_client()

    response = client.get(
        "/auth/me",
        headers=_headers(
            provider="oidc",
            claims={
                "sub": "editor-001",
                "preferred_username": "Editor.User",
                "name": "Editor User",
                "email": "editor@example.com",
                "groups": ["finance-editors"],
                "roles": ["validator"],
            },
        ),
    )

    assert response.status_code == 200
    assert response.json() == {
        "actor_id": "oidc:editor-001",
        "provider": "oidc",
        "subject": "editor-001",
        "username": "editor.user",
        "display_name": "Editor User",
        "email": "editor@example.com",
        "groups": ["finance-editors"],
        "roles": ["validator"],
        "permissions": [
            "documents.read",
            "documents.validate",
            "documents.write",
        ],
    }


def test_protected_endpoint_returns_401_for_anonymous_and_403_for_unauthorized() -> None:
    client, writer, audit = _build_client()

    anonymous_response = client.post(
        "/auth/protected-write",
        json={"target_id": "doc-1", "payload": {"status": "validated"}},
    )

    unauthorized_response = client.post(
        "/auth/protected-write",
        headers=_headers(
            provider="saml",
            claims={
                "nameid": "reviewer@example.com",
                "http://schemas.xmlsoap.org/claims/group": ["finance-readers"],
            },
        ),
        json={"target_id": "doc-1", "payload": {"status": "validated"}},
    )

    assert anonymous_response.status_code == 401
    assert anonymous_response.json()["detail"] == "Authentication required."
    assert unauthorized_response.status_code == 403
    assert unauthorized_response.json()["detail"] == "Caller does not have the required permission."
    assert writer.commands == []
    assert audit.events == []


def test_successful_write_propagates_actor_identity_to_write_and_audit_paths() -> None:
    client, writer, audit = _build_client()

    response = client.post(
        "/auth/protected-write",
        headers=_headers(
            provider="oidc",
            claims={
                "sub": "editor-123",
                "preferred_username": "editor",
                "groups": ["finance-editors"],
            },
        ),
        json={"target_id": "doc-22", "payload": {"field": "value"}},
    )

